function windows(toks, size, stride) {
  const out = [];
  for (let start = 0; start < toks.length; start += stride) {
    out.push(toks.slice(start, start + size));
    if (start + size >= toks.length) break;
  }
  return out;
}
const ws = windows(tokens, SIZE, STRIDE);
