const lexical = ["d3", "d2", "d1"];
const vector = ["d2", "d1", "d4"];
const K = 60;
function fuse(lists, k) {
  const score = new Map();
  for (const list of lists) list.forEach((id, i) => score.set(id, (score.get(id) ?? 0) + 1 / (k + (i + 1))));
  return [...score.entries()]
    .map(([id, s]) => ({ id, score: s }))
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
}
const fused = fuse([lexical, vector], K);
for (const r of fused) console.log(`${r.id}=${r.score.toFixed(5)}`);
const changed = lexical[0] !== fused[0].id ? "yes" : "no";
console.log(`lexical#1: ${lexical[0]}  fused#1: ${fused[0].id}  changed: ${changed}`);

reranking.code:
const query = "refund window policy";
const stage1 = [
  { id: "a", text: "shipping and delivery times" },
  { id: "b", text: "our refund policy and refund window" },
  { id: "c", text: "policy for enterprise plans" },
  { id: "d", text: "password reset instructions" },
];
const K = 2;
function rerank(query, docs) {
  const terms = query.toLowerCase().split(/\s+/);
  return [...docs]
    .map((d) => {
      const words = new Set(d.text.toLowerCase().split(/\s+/));
      const rel = terms.filter((t) => words.has(t)).length;
      return { id: d.id, rel };
    })
    .sort((a, b) => b.rel - a.rel || a.id.localeCompare(b.id))
    .slice(0, K)
    .map((x) => x.id);
}
const top3 = stage1.slice(0, 3);
console.log(`stage1: ${top3.map((d) => d.id).join(",")}`);
console.log(`reranked: ${rerank(query, top3).join(",")}`);

