const glossary = { "SLA": "service level agreement", "refund": "money-back guarantee" };
const queries = [
  "what is the SLA?",
  "how do I get a refund?",
  "reset my password",
];
function expand(query, glossary) {
  let out = query;
  for (const [alias, canonical] of Object.entries(glossary)) {
    out = out.replace(new RegExp(`\\b${alias}\\b`, "gi"), canonical);
  }
  return out;
}
